BEGIN;
CREATE TABLE university_departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL,name text NOT NULL,division text NOT NULL,status text NOT NULL CHECK(status IN ('planned','active','paused','retired')),service_target_minutes integer NOT NULL CHECK(service_target_minutes>0),privacy_class text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,code));
CREATE TABLE department_staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),department_id uuid NOT NULL REFERENCES university_departments(id),user_id uuid NOT NULL REFERENCES users(id),position_code text NOT NULL,role_scope jsonb NOT NULL DEFAULT '[]',starts_at timestamptz NOT NULL,ends_at timestamptz,supervisor_user_id uuid REFERENCES users(id),status text NOT NULL CHECK(status IN ('pending','active','leave','ended')),UNIQUE(department_id,user_id,position_code,starts_at));
CREATE TABLE student_service_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),department_id uuid NOT NULL REFERENCES university_departments(id),student_user_id uuid REFERENCES users(id),requester_type text NOT NULL CHECK(requester_type IN ('prospect','applicant','student','alumni','parent_authorized','employee','public')),topic text NOT NULL,subject text NOT NULL,description_encrypted bytea NOT NULL,priority text NOT NULL CHECK(priority IN ('routine','priority','urgent','critical')),status text NOT NULL CHECK(status IN ('received','triaged','assigned','waiting_student','waiting_internal','resolved','closed','appealed')),assigned_to uuid REFERENCES users(id),consent_version text NOT NULL,source_channel text NOT NULL,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE service_case_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),case_id uuid NOT NULL REFERENCES student_service_cases(id),sender_user_id uuid REFERENCES users(id),direction text NOT NULL CHECK(direction IN ('inbound','outbound','internal')),body_encrypted bytea NOT NULL,delivery_status text NOT NULL CHECK(delivery_status IN ('draft','approval_required','approved','queued','sent','delivered','failed')),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(delivery_status NOT IN ('approved','queued','sent','delivered') OR approved_by IS NOT NULL));
CREATE TABLE advising_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),case_id uuid REFERENCES student_service_cases(id),student_user_id uuid NOT NULL REFERENCES users(id),advisor_user_id uuid REFERENCES users(id),appointment_type text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('requested','confirmed','completed','cancelled','no_show')),accommodation_notes_encrypted bytea,CHECK(ends_at>starts_at));
CREATE TABLE social_service_referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),case_id uuid NOT NULL REFERENCES student_service_cases(id),student_user_id uuid NOT NULL REFERENCES users(id),need_category text NOT NULL,consent_at timestamptz,provider_name text,provider_contact_encrypted bytea,status text NOT NULL CHECK(status IN ('assessment','consent_pending','referred','follow_up','closed','declined')),referred_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'referred' OR (consent_at IS NOT NULL AND referred_by IS NOT NULL)));
CREATE TABLE financial_aid_readiness_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_user_id uuid NOT NULL REFERENCES users(id),aid_year text NOT NULL,status text NOT NULL CHECK(status IN ('information_only','documents_pending','eligibility_blocked','external_referral','closed')),fafsa_completion_self_reported boolean,dependency_status text,verification_flags jsonb NOT NULL DEFAULT '[]',assigned_officer uuid REFERENCES users(id),title_iv_transaction_id text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(title_iv_transaction_id IS NULL));
CREATE TABLE student_billing_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_user_id uuid NOT NULL REFERENCES users(id),currency char(3) NOT NULL DEFAULT 'USD',status text NOT NULL CHECK(status IN ('planned','open','hold','closed')),balance_cents bigint NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,student_user_id));
CREATE TABLE student_ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),billing_account_id uuid NOT NULL REFERENCES student_billing_accounts(id),entry_type text NOT NULL CHECK(entry_type IN ('charge','credit','payment_pending','refund_pending','adjustment','writeoff')),amount_cents bigint NOT NULL,description text NOT NULL,source_reference text NOT NULL,posted_by uuid REFERENCES users(id),approved_by uuid REFERENCES users(id),posted_at timestamptz NOT NULL DEFAULT now(),reversed_by_entry_id uuid REFERENCES student_ledger_entries(id),CHECK(entry_type NOT IN ('credit','refund_pending','adjustment','writeoff') OR approved_by IS NOT NULL));
CREATE TABLE institutional_accounting_mappings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),source_type text NOT NULL,source_code text NOT NULL,debit_account text NOT NULL,credit_account text NOT NULL,effective_at timestamptz NOT NULL,approved_by uuid NOT NULL REFERENCES users(id),UNIQUE(tenant_id,source_type,source_code,effective_at));
CREATE INDEX service_case_queue ON student_service_cases(tenant_id,department_id,status,priority,created_at);CREATE INDEX service_message_delivery ON service_case_messages(tenant_id,delivery_status,created_at);CREATE INDEX advising_calendar ON advising_appointments(tenant_id,starts_at,status);CREATE INDEX aid_readiness_queue ON financial_aid_readiness_cases(tenant_id,status,created_at);CREATE INDEX student_ledger_account ON student_ledger_entries(tenant_id,billing_account_id,posted_at);
ALTER TABLE university_departments ENABLE ROW LEVEL SECURITY;ALTER TABLE department_staff_assignments ENABLE ROW LEVEL SECURITY;ALTER TABLE student_service_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE service_case_messages ENABLE ROW LEVEL SECURITY;ALTER TABLE advising_appointments ENABLE ROW LEVEL SECURITY;ALTER TABLE social_service_referrals ENABLE ROW LEVEL SECURITY;ALTER TABLE financial_aid_readiness_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE student_billing_accounts ENABLE ROW LEVEL SECURITY;ALTER TABLE student_ledger_entries ENABLE ROW LEVEL SECURITY;ALTER TABLE institutional_accounting_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY university_departments_tenant ON university_departments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY department_staff_tenant ON department_staff_assignments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY student_service_cases_tenant ON student_service_cases USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY service_case_messages_tenant ON service_case_messages USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY advising_appointments_tenant ON advising_appointments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY social_service_referrals_tenant ON social_service_referrals USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY aid_readiness_cases_tenant ON financial_aid_readiness_cases USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY student_billing_accounts_tenant ON student_billing_accounts USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY student_ledger_entries_tenant ON student_ledger_entries USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY accounting_mappings_tenant ON institutional_accounting_mappings USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
